ROWS = [
    {"zone": "north", "reading": "12"},
    {"zone": "east", "reading": "7"},
    {"zone": "south", "reading": "warm"},
]


def total_readings(rows):
    total = 0
    for row in rows:
        try:
            total += int(row["reading"])
        except ValueError:
            continue
    return total


def skipped(rows):
    count = 0
    for row in rows:
        try:
            int(row["reading"])
        except ValueError:
            count += 1
    return count


print(total_readings(ROWS))
